static inline float compute_tree_depth(const Node* tree, int node_id, const float* x) {
    if (tree[node_id].left_child == -1) return 1.0f;
    int feat = tree[node_id].feature;
    if (x[feat] <= tree[node_id].threshold) {
        return 1.0f + compute_tree_depth(tree, tree[node_id].left_child, x);
    } else {
        return 1.0f + compute_tree_depth(tree, tree[node_id].right_child, x);
    }
}

